#include <iostream>
#include <cstring>
#include <cstdio>
using namespace std;

#define M 1000007

char a[30];
int n, ans = 0;
bool b[M];

inline void Insert(int x, char y) {
    int e = 0;
    for (int i = 0; i < x; ++i)
        e = (e * 39 + a[i]) % M;

    e = (e * 39 + y) % M;

    for (int i = x; i < n; ++i)
        e = (e * 39 + a[i]) % M;

    if (b[e]) return;
    b[e] = true;
    ++ans;
}

int main() {
    scanf("%29s", a);
    n = strlen(a);

    for (int i = 0; i <= n; ++i)
        for (char j = 'a'; j <= 'z'; ++j)
            Insert(i, j);

    cout << ans << '\n';
    return 0;
}

